    await page.keyboard.up('ShiftRight');
    await page.keyboard.press('Semicolon');
    await expect(page.getByRole('dialog', { name: 'Paused', exact: true })).toBeVisible();
    await page.reload();
    expect([...(await saved()).h1]).toEqual([...'ShiftLeft']);
    expect(errors).toEqual([]);
  });
